/* HEXA BATTLEGROUNDS setup — PART 25 OF 83. Run parts in order. Safe to re-run. */ create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 0, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6, 'move_speed', 25, 'loc_radius', 35, 'engage_range', 60, 'zone_tick_seconds', 6, 'zone_tick_damage', 4, 'red_interval', 0, 'red_warning', 20, 'red_damage', 30, 'red_radius', 80 ) || jsonb_build_object( 'reveal_pct', 50 ) $$; create or replace function _loc_xy(p_loc text) returns float8[] language sql stable as $$ select array[x::float8, y::float8] from locations where id = p_loc $$; create or replace function _team_xy(t teams) returns float8[] language plpgsql stable as $$ declare d float8[]; p float8; begin if t.state = 'traveling' and t.travel_to is not null and t.travel_arrive_at is not null then d := _loc_xy(t.travel_to); if t.travel_fx is not null and d is not null then p := least(1, greatest(0, extract(epoch from now() - t.travel_started_at) / greatest(0.001, extract(epoch from t.travel_arrive_at - t.travel_started_at)))); return array[t.travel_fx + (d[1] - t.travel_fx) * p, t.travel_fy + (d[2] - t.travel_fy) * p]; end if; end if; if t.pos_x is not null then return array[t.pos_x::float8, t.pos_y::float8]; end if; return coalesce(_loc_xy(t.location_id), array[0.5, 0.93]); end $$; create or replace function _complete(p_instance uuid) returns int language plpgsql as $$ declare mi mission_instances; mt mission_templates; t teams; l locations; sr sync_rounds; v_ev uuid; v_pts int := 0; v_coins int := 0; v_item text; v_won boolean; ad airdrops; v_total numeric; v_left numeric; begin select * into mi from mission_instances where id = p_instance for update; if mi.status <> 'active' then return 0; end if; select * into mt from mission_templates where id = mi.template_id; select * into t from teams where id = mi.team_id; v_ev := t.event_id; update mission_instances set status = 'solved', solved_at = now() where id = mi.id; if mi.kind = 'battle' then perform 1 from battles where id = mi.battle_id for update; if exists (select 1 from battles where id = mi.battle_id and status = 'active') then perform _resolve_battle(mi.battle_id, mi.team_id); return _cfg(v_ev, 'pts_battle'); end if; update mission_instances set status = 'failed' where id = mi.id; return 0; elsif mi.kind = 'recovery' then perform _respawn(mi.team_id, 'solved'); return 0; elsif mi.sync_round_id is not null then select * into sr from sync_rounds where id = mi.sync_round_id; v_total := greatest(1, extract(epoch from sr.deadline - sr.started_at)); v_left := greatest(0, extract(epoch from sr.deadline - now())); v_pts := round(sr.max_points * (0.5 + 0.5 * v_left / v_total)); if mt.relay and mi.fallback_at is not null and now() >= mi.fallback_at then v_pts := v_pts / 2; end if; if mi.hint_used then v_pts := round(v_pts * 0.8); end if; perform _apply(mi.team_id, 'finale', v_pts, 0, 0, 0, mi.id::text, mt.title); update teams set final_points = final_points + v_pts where id = mi.team_id; elsif mi.kind = 'airdrop' then update airdrops set claimed_by = mi.team_id, claimed_at = now(), status = 'claimed' where id = mi.airdrop_id and claimed_by is null and status = 'open' returning * into ad; v_won := ad.id is not null; if v_won then v_pts := _cfg(v_ev, 'pts_airdrop'); v_coins := case ad.tier when 'common' then 40 when 'rare' then 60 when 'legendary' then 100 when 'mystery' then 20 + abs(hashtext(ad.id::text)) % 101 when 'cursed' then 0 else 30 end; if ad.tier = 'cursed' then v_pts := v_pts * 2; end if; if t.beacon then v_coins := v_coins * 2; update teams set beacon = false where id = t.id; end if; perform _apply(mi.team_id, 'airdrop', v_pts, v_coins, 0, 0, ad.id::text, ad.tier || ' airdrop'); if ad.tier = 'cursed' then perform _damage(mi.team_id, 20, 'curse', ad.id::text, 'Cursed airdrop'); end if; if ad.tier = 'intel' then update teams set scan_until = now() + interval '120 seconds' where id = t.id; end if; v_item := case ad.tier when 'legendary' then 'sniper' when 'rare' then 'shield' when 'common' then 'medkit' when 'mystery' then (array['smg', 'jammer', 'scanner', 'extract'])[1 + abs(hashtext(ad.id::text || 'i')) % 4] else null end; if v_item is not null then perform _add_item(mi.team_id, v_item, 1); end if; if ad.tier = 'legendary' then perform _add_item(mi.team_id, 'shield', 1); end if; perform _feed(t.arena_id, 'airdrop.claimed', jsonb_build_object('team', t.number, 'tier', ad.tier, 'location', ad.location_id)); update mission_instances set status = 'cancelled' where airdrop_id = mi.airdrop_id and status = 'active' and id <> mi.id; perform _ping_arena(t.arena_id, 'airdrop'); else perform _apply(mi.team_id, 'airdrop_consolation', 0, 15, 0, 0, mi.id::text, 'Airdrop already taken'); end if; else v_pts := coalesce(mt.points, case when mt.difficulty >= 2 then _cfg(v_ev, 'pts_hard') else _cfg(v_ev, 'pts_standard') end); v_coins := mt.coins; if mt.relay then if mi.fallback_at is not null and now() >= mi.fallback_at then v_pts := v_pts / 2; elsif mi.partner_team_id is not null then perform _apply(mi.partner_team_id, 'relay_assist', _cfg(v_ev, 'pts_relay_bonus'), 0, 0, 10, mi.id::text, 'Shared a codeword'); perform _apply(mi.team_id, 'relay_trust', 0, 0, 0, 5, mi.id::text, 'Cooperated'); perform _feed(t.arena_id, 'intel.shared', jsonb_build_object('from', (select number from teams where id = mi.partner_team_id), 'to', t.number)); perform _ping_team(mi.partner_team_id, 'intel'); end if; end if; perform _apply(mi.team_id, 'mission', v_pts, v_coins, 0, 0, mi.id::text, mt.title); update teams set missions_completed = missions_completed + 1 where id = mi.team_id; select * into l from locations where id = mi.location_id; if l.id is not null and array_length(l.loot, 1) > 0 then v_item := l.loot[1 + abs(hashtext(mi.id::text)) % array_length(l.loot, 1)]; perform _add_item(mi.team_id, v_item, 1); end if; end if; update mission_instances set points_awarded = v_pts where id = mi.id; perform _feed(t.arena_id, 'mission.completed', jsonb_build_object('team', t.number, 'title', mt.title, 'points', v_pts, 'item', v_item)); perform _ping_team(mi.team_id, 'result'); perform _ping_arena(t.arena_id, 'score'); return v_pts; end $$; create or replace function _reveal_cost(mi mission_instances) returns int language plpgsql stable as $$ declare mt mission_templates; v_ev uuid; v_base int; v_n int; begin if mi.kind not in ('mission', 'relay', 'recovery') or mi.sync_round_id is not null or mi.airdrop_id is not null then return 0; end if; select * into mt from mission_templates where id = mi.template_id; select event_id into v_ev from teams where id = mi.team_id; v_base := coalesce(mt.points, case when mt.difficulty >= 2 then _cfg(v_ev, 'pts_hard') else _cfg(v_ev, 'pts_standard') end); select count(*) into v_n from jsonb_array_elements(mt.parts) x where not (x -> 'accept') ? '{KEY}'; if v_n = 0 then return 0; end if; return greatest(5, ceil(v_base * _cfg(v_ev, 'reveal_pct') / 100.0 / v_n))::int; end $$; create or replace function captain_reveal(p_token text, p_instance uuid, p_part int) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; mi mission_instances; mt mission_templates; v_part jsonb; v_cost int; v_ans text; begin p := _auth_captain(p_token); select * into mi from mission_instances where id = p_instance for update; if mi.id is null or mi.team_id <> p.team_id or mi.status <> 'active' then raise exception 'NOT_FOUND'; end if; v_cost := _reveal_cost(mi); if v_cost = 0 then raise exception 'NO_REVEAL_HERE'; end if; select * into mt from mission_templates where id = mi.template_id; v_part := mt.parts -> p_part; if v_part is null or (v_part -> 'accept') ? '{KEY}' then raise exception 'NO_REVEAL_HERE'; end if; v_ans := v_part -> 'accept' ->> 0; if mi.revealed ? p_part::text then return jsonb_build_object('part', p_part, 'answer', v_ans, 'cost', 0); end if; perform _apply(mi.team_id, 'reveal', -v_cost, 0, 0, 0, mi.id::text || ':' || p_part, 'Revealed an answer'); update mission_instances set revealed = revealed || jsonb_build_object(p_part::text, v_ans) where id = mi.id; perform _ping_team(mi.team_id, 'hint'); return jsonb_build_object('part', p_part, 'answer', v_ans, 'cost', v_cost); end $$;
